window.reportPurchases=function(period,{returnsOnly=false}={}){const rows=[];(db.purchases||[]).filter(p=>!purchaseIsDraft(p)).forEach(p=>{const st=state(p);if(returnsOnly){const events=Array.isArray(p.returns)?p.returns:[];if(events.length){events.forEach(r=>{const date=r?.date||p.purchaseReturnedAt||p.partialReturnedAt||p.date,d=new Date(date);if(Number.isNaN(d.getTime())||d<period.start||d>period.end)return;const amount=Math.max(0,num(r?.amount)),qty=Math.max(0,num(r?.totalQty)||sum(Array.isArray(r?.items)?r.items:[],x=>num(x?.qty)));if(amount<=EPS&&qty<=EPS)return;rows.push({...p,id:String(r?.id||p.id||'Retur Pembelian'),purchaseId:String(p.id||''),date,total:amount,paid:amount,items:qty,returnedAmount:amount,returnEvent:r,returnReport:true})})}else if(st.returnedAmount>EPS){const date=p.purchaseReturnedAt||p.partialReturnedAt||p.updatedAt||p.date,d=new Date(date);if(!Number.isNaN(d.getTime())&&d>=period.start&&d<=period.end)rows.push({...p,date,total:st.returnedAmount,paid:st.returnedAmount,items:st.returnedQty,returnReport:true})}}else{const d=new Date(p.date);if(Number.isNaN(d.getTime())||d<period.start||d>period.end||st.netTotal<=EPS)return;rows.push({...p,total:st.netTotal,items:st.remainingQty})}});return rows};
